<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Token Radar — pre-token protocols ranked by implied value</title>
<link rel="icon" href="data:,">
<link rel="stylesheet" href="app.css">
</head>
<body>
<header class="top">
  <div class="brand">
    <span class="pulse" aria-hidden="true"></span>
    <h1>Token Radar</h1>
    <p class="tagline">Pre-token protocols, ranked by what a launch would be worth — from the snapshot's own figures.</p>
  </div>
  <dl class="stats" id="stats"></dl>
</header>

<nav class="tabs" aria-label="Views">
  <button type="button" data-tab="board" class="active" aria-pressed="true">Ranked board</button>
  <button type="button" data-tab="live" aria-pressed="false">Live tokens</button>
</nav>

<section class="controls" aria-label="Filter the board">
  <label>Search <input type="search" id="q" placeholder="Name or slug…" autocomplete="off"></label>
  <label>Category <select id="category"><option value="all">All categories</option></select></label>
