          <th data-sort="category">Category</th>
          <th data-sort="chains">Chains</th>
          <th data-sort="tvl_usd" class="num">TVL</th>
          <th data-sort="change_7d" class="num">7d</th>
          <th data-sort="age_days" class="num">Age</th>
          <th data-sort="implied_value_usd" class="num">Implied value</th>
        </tr>
      </thead>
      <tbody id="rows"></tbody>
    </table>
    <table id="live" hidden>
      <thead>
        <tr>
          <th>Protocol</th>
          <th>Category</th>
          <th>Chains</th>
          <th class="num">TVL</th>
          <th class="num">Market cap</th>
          <th class="num">7d</th>
        </tr>
      </thead>
      <tbody id="liveRows"></tbody>
    </table>
